-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS REPORT_DATE,     oh.ORDER_NO                                           AS PO_NUMBER,     oh.STATUS                                             AS PO_STATUS,     oh.SUPPLIER                                           AS SUPPLIER_ID,     sp.SUP_NAME                                           AS SUPPLIER_NAME,     os.ITEM                                               AS ITEM_ID,     im.ITEM_DESC                                          AS ITEM_DESCRIPTION,     im.DEPT                                               AS DEPT_NO,     d.DEPT_NAME                                           AS DEPT_NAME,     os.ORIGIN_COUNTRY_ID                                  AS ORIGIN_COUNTRY,     olc.LOCATION                                          AS LOCATION,     ieh.ITEM_EXP_SEQ                                      AS ITEM_EXP_SEQ,     ieh.ITEM_EXP_TYPE                                     AS ITEM_EXP_TYPE,     ol.COMP_ID                                            AS COST_COMPONENT_ID,     ied.COMP_RATE                                         AS COMPONENT_RATE,     ied.COMP_CURRENCY                                     AS COMPONENT_CURRENCY,      CASE         WHEN ieh.ITEM_EXP_SEQ IS NULL THEN 'MISSING EXPENSE PROFILE'         WHEN ied.COMP_RATE IS NULL    THEN 'MISSING COMPONENT RATE'         WHEN ol.COMP_ID IS NULL       THEN 'MISSING ORDLOC EXPENSE LINK'         ELSE 'OK'     END                                                    AS VALIDATION_STATUS  FROM  MFCS_RDS.RDS_WV_ORDHEAD                 oh JOIN  MFCS_RDS.RDS_WV_ORDSKU                  os   ON oh.ORDER_NO = os.ORDER_NO JOIN  MFCS_RDS.RDS_WV_ORDLOC                  olc  ON oh.ORDER_NO = olc.ORDER_NO JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             im   ON os.ITEM     = im.ITEM JOIN  MFCS_RDS.RDS_WV_DEPS                    d    ON im.DEPT     = d.DEPT LEFT JOIN MFCS_RDS.RDS_WV_SUPS                sp   ON oh.SUPPLIER = sp.SUPPLIER  LEFT JOIN MFCS_RDS.RDS_WV_ITEM_EXP_HEAD       ieh  ON os.ITEM               = ieh.ITEM                                                     AND os.ORIGIN_COUNTRY_ID = ieh.ORIGIN_COUNTRY_ID                                                     AND oh.SUPPLIER          = ieh.SUPPLIER  LEFT JOIN MFCS_RDS.RDS_WV_ITEM_EXP_DETAIL     ied  ON ieh.ITEM             = ied.ITEM                                                     AND ieh.ITEM_EXP_SEQ    = ied.ITEM_EXP_SEQ                                                     AND ieh.ITEM_EXP_TYPE   = ied.ITEM_EXP_TYPE                                                     AND ieh.SUPPLIER        = ied.SUPPLIER  LEFT JOIN MFCS_RDS.RDS_WV_ORDLOC_EXP          ol   ON oh.ORDER_NO = ol.ORDER_NO                                                     AND olc.LOCATION = ol.LOCATION                                                     AND os.ITEM      = ol.ITEM                                                     AND ol.COMP_ID   = ied.COMP_ID  WHERE     oh.STATUS IN ('W','S','A')     AND oh.WRITTEN_DATE BETWEEN ADD_MONTHS(SYSDATE, -3) AND TRUNC(SYSDATE)  ORDER BY oh.ORDER_NO, os.ITEM</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>REPORT_DATE</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>PO_NUMBER</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>PO_STATUS</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER_ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER_NAME</ds:name><ds:datatype>varchar(240)</ds:datatype></ds:column><ds:column><ds:name>ITEM_ID</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>ITEM_DESCRIPTION</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPT_NO</ds:nam